// x86_64 4-Level Page Table Structure
// Virtual Address (64-bit): [Sign Ext 16b | PML4 9b | Directory 9b | Page Table 9b | Offset 12b]

uint64_t translateAddress(uint64_t virtualAddress) {
    uint64_t pml4_index = (virtualAddress >> 39) & 0x1FF;
    uint64_t pdpt_index = (virtualAddress >> 30) & 0x1FF;
    uint64_t offset     = virtualAddress & 0xFFF;
    return (physicalFrameBase << 12) | offset;
}
